/*
 * carv_e.c: UCX-OS image of a composition of applications generated by
 * rttools.ucxgen (orca-rt-tools). Do not edit: change the inputs and run
 * the generator again.
 *
 *   python -m rttools.ucxgen compose --app CARV:car-v.csv:CARV.map --app E:synthetic-app-e.csv:E.map \
 *     --name carv_e --mesh 4x5 --cycles-per-count 10 \
 *     --payload-divisor 1 --tag-mod 1024 --delay-ns 3000000
 *
 * CARV: car-v.csv (sha256 f2d3d1d0d6d01b1139f2ce6902adad589e36502243cf5202cd6b7d383c23caa0)
 *       CARV.map (sha256 63587e41328f19befd5e8d9267aab1f569f206704910f7b9e4fbda429e7ea2c3)
 *       23 tasks, flows 1 to 23, PEs 0, 1, 2, 3, 4, 5, 6, 7, 8, 11, 12, 15, 16, 17, 18, 19, reserve 11000 cycles
 * E: synthetic-app-e.csv (sha256 522dcca19a8df3bc57c2ad86f28a9d9e51f81075906bbb1179a28b057fa1efe5)
 *    E.map (sha256 9df9a3c64b52ae4eff323c745e49eb47439d1ed2efaa33afec9c6531116a0303)
 *    10 tasks, flows 24 to 34, PEs 9, 10, 13, 14, reserve 11000 cycles
 * 33 tasks, 34 flows (21 between PEs), mesh 4x5; release every
 * 500000 ns after 3000000 ns on the PEs of the source tasks (1, 2, 3, 7, 8, 11, 12, 14, 16).
 *
 * Each PE runs the tasks of one application. Ports, flow numbers (tags)
 * and marker letters are numbered across the applications in the order
 * above, so a tag or a letter of the log identifies its application
 * (manifest carv_e.json, field "apps"). The task pattern is the one of an
 * application of rttools.ucxgen generate (see the header of a generated
 * application, e.g. car_v.c): release of the source tasks by
 * irq4_handler, k-th packet of each input edge, ucx_sleep(workload), one
 * send per output edge, tag = flow * TAG_MOD + (k mod TAG_MOD), ITER
 * markers.
 *
 * Release by tick (built with -DUCX_TICK_RELEASE: the Makefile rule of the
 * generated applications, TR_DEFS; lib/tick_release.c): the release
 * generator fires on every PE with a task (app/carv_e.sim), the release
 * interrupt counts the phases, and the tick hook of the kernel wakes the
 * tasks whose phase has come. Task v waits for the tick of phase
 * k + n(v) (TASK_PHASE: phase index of the model of the analysis flow,
 * field "phase" of the manifest) before it reads the input of iteration k
 * (FIFO), so it runs at most once per phase and serves iteration k from
 * the tick of phase k + n(v). Without the macro, the code is the pattern
 * above (data-driven release of the runs CV, CV2 and MA: a run serves
 * every iteration whose packets are in the queue).
 */
#include <ucx.h>

#define N_TASKS     33
#define MAX_IN      4
#define MAX_OUT     2
#define MAX_RELEASE 1
#define TAG_MOD     1024
#define TAG(flow, k) ((uint16_t)((flow) * TAG_MOD + ((k) % TAG_MOD)))
#define ITERATIONS  99999

struct out_s {
  uint16_t cpu;    /* PE of the target task (node index) */
  uint16_t port;   /* port of the target task */
  uint16_t bytes;  /* payload */
  uint16_t flow;   /* index of the edge (tag) */
};

struct task_s {
  char name[5];
  char letter;                    /* letter of the iteration markers */
  uint16_t port;
  int32_t workload;               /* counts of ucx_sleep */
  uint8_t n_in, n_out;
  uint16_t in_port[MAX_IN];       /* port of the source task of each input edge */
  struct out_s out[MAX_OUT];
};

