void idle_task_p(void)
{
#ifdef UCX_TICK_RELEASE
  /* a yield can enter the idle task with interrupts disabled (kernel/sched.c) */
  _ei();
#endif
  for (;;)
    ;
}

static void add_task(void (*fn)(void), const struct task_s *t)
{
  ucx_task_add(fn, (char *)t->name, DEFAULT_STACK_SIZE, 0, 0, 0);
#ifndef UCX_TICK_RELEASE
  if (t->n_in == 0 && n_release < MAX_RELEASE)
    release_tcb[n_release++] = kcb_p->tcb_p;   /* tcb of the task just added */
#endif
}

int32_t app_main(void)
{
  /* idle must be ID = 0 */
  ucx_task_add(idle_task_p, "IDLE", DEFAULT_STACK_SIZE, 0, 0, 0);

  switch (ucx_noc_cpu_id()) {
  case 0: /* (0-0): NAVC */
    add_task(task_CARV_NAVC, &TASKS[8]);
    break;
  case 1: /* (1-0): FBU4, BFE4 */
    add_task(task_CARV_FBU4, &TASKS[3]);
    add_task(task_CARV_BFE4, &TASKS[12]);
    break;
  case 2: /* (2-0): FBU1, BFE1 */
    add_task(task_CARV_FBU1, &TASKS[0]);
    add_task(task_CARV_BFE1, &TASKS[9]);
    break;
  case 3: /* (3-0): FBU2, BFE2 */
    add_task(task_CARV_FBU2, &TASKS[1]);
    add_task(task_CARV_BFE2, &TASKS[10]);
    break;
  case 4: /* (0-1): BFE3 */
    add_task(task_CARV_BFE3, &TASKS[11]);
    break;
  case 5: /* (1-1): BFE7 */
    add_task(task_CARV_BFE7, &TASKS[15]);
    break;
  case 6: /* (2-1): BFE8 */
    add_task(task_CARV_BFE8, &TASKS[16]);
    break;
  case 7: /* (3-1): FBU5, BFE5 */
    add_task(task_CARV_FBU5, &TASKS[4]);
    add_task(task_CARV_BFE5, &TASKS[13]);
    break;
  case 8: /* (0-2): FBU8, VOD2 */
    add_task(task_CARV_FBU8, &TASKS[7]);
    add_task(task_CARV_VOD2, &TASKS[21]);
    break;
  case 9: /* (1-2): J, G */
    add_task(task_E_J, &TASKS[32]);
    add_task(task_E_G, &TASKS[29]);
    break;
  case 10: /* (2-2): C */
    add_task(task_E_C, &TASKS[25]);
    break;
  case 11: /* (3-2): FBU6, BFE6 */
    add_task(task_CARV_FBU6, &TASKS[5]);
    add_task(task_CARV_BFE6, &TASKS[14]);
    break;
  case 12: /* (0-3): FBU3, VOD1 */
    add_task(task_CARV_FBU3, &TASKS[2]);
    add_task(task_CARV_VOD1, &TASKS[20]);
    break;
  case 13: /* (1-3): H, I, E */
    add_task(task_E_H, &TASKS[30]);
    add_task(task_E_I, &TASKS[31]);
    add_task(task_E_E, &TASKS[27]);
    break;
  case 14: /* (2-3): F, D, B, A */
    add_task(task_E_F, &TASKS[28]);
    add_task(task_E_D, &TASKS[26]);
    add_task(task_E_B, &TASKS[24]);
    add_task(task_E_A, &TASKS[23]);
    break;
  case 15: /* (3-3): OBMG */
    add_task(task_CARV_OBMG, &TASKS[22]);
    break;
  case 16: /* (0-4): FBU7 */
    add_task(task_CARV_FBU7, &TASKS[6]);
    break;
  case 17: /* (1-4): STPH */
    add_task(task_CARV_STPH, &TASKS[19]);
    break;
  case 18: /* (2-4): FDF2 */
    add_task(task_CARV_FDF2, &TASKS[18]);
    break;
  case 19: /* (3-4): FDF1 */
    add_task(task_CARV_FDF1, &TASKS[17]);
    break;
  default:
    break;
  }

  return 1;
}
